    br[2] = INV_SQRT2 * (ar[0] - ar[2]);
    bi[2] = INV_SQRT2 * (ai[0] - ai[2]);
    br[1] = INV_SQRT2 * (ar[1] + ar[3]);
    bi[1] = INV_SQRT2 * (ai[1] + ai[3]);
    br[3] = INV_SQRT2 * (ar[1] - ar[3]);
    bi[3] = INV_SQRT2 * (ai[1] - ai[3]);

    /* gate: CNOT(q0,q1) */
    ar[0] = br[0];
    ai[0] = bi[0];
    ar[1] = br[1];
    ai[1] = bi[1];
    ar[2] = br[3];
    ai[2] = bi[3];
    ar[3] = br[2];
    ai[3] = bi[2];

    /* Target GHZ amplitudes: (|0..0> + |1..1>)/sqrt(2). */
    __ESBMC_assert(ar[0] >= INV_SQRT2 - 0.001 && ar[0] <= INV_SQRT2 + 0.001 && ar[3] >= INV_SQRT2 - 0.001 && ar[3] <= INV_SQRT2 + 0.001 && ai[0] >= -0.001 && ai[0] <= 0.001 && ai[1] >= -0.001 && ai[1] <= 0.001 && ar[1] >= -0.001 && ar[1] <= 0.001 && ai[2] >= -0.001 && ai[2] <= 0.001 && ar[2] >= -0.001 && ar[2] <= 0.001 && ai[3] >= -0.001 && ai[3] <= 0.001,
                   "GHZ-2 amplitudes diverge from target");
